import React from 'react';
import { Card, CardContent, Box, Typography, useTheme, useMediaQuery, FormControl, Select, MenuItem } from '@mui/material';
import { LineChart } from '@mui/x-charts/LineChart';
import { alpha } from '@mui/material/styles';

const ServerInfoLineChart = ({
  title,
  data,
  dataKey,
  color = '#8884d8',
  sx,
  yAxisTickFormatter,
  tooltipFormatter,
  loading = false,
  IconComponent,
}) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const hasData = Array.isArray(data) && data.length > 0;

  // Transform data for @mui/x-charts
  const chartData = React.useMemo(() => {
    if (!hasData) return [];
    
    const transformed = data.map((item, index) => ({
      id: index,
      date: item.date,
      value: Number(item[dataKey]) || 0,
    }));
    
    return transformed;
  }, [data, dataKey, hasData]);

  // Custom tooltip formatter
  const formatTooltip = React.useCallback((params) => {
    if (!params || params.length === 0) return null;
    
    const item = params[0];
    if (tooltipFormatter) {
      try {
        const result = tooltipFormatter(item.value, item.date);
        if (Array.isArray(result) && result.length >= 2) {
          return `${result[1]}: ${result[0]}`;
        }
        return `${item.date}: ${item.value}`;
      } catch (error) {
        return `${item.date}: ${item.value}`;
      }
    }
    return `${item.date}: ${item.value}`;
  }, [tooltipFormatter]);

  // Unique gradient id per instance
  const rawId = React.useId();
  const gradientId = React.useMemo(() => `lineAreaGradient-${String(rawId).replace(/:/g, '-')}`, [rawId]);

  // Compute y-axis domain to have exactly 4 non-zero ticks (plus 0), and hide 0 label
  const niceStep = React.useCallback((raw) => {
    if (!isFinite(raw) || raw <= 0) return 1;
    const power = Math.pow(10, Math.floor(Math.log10(raw)));
    const n = raw / power;
    let s;
    if (n <= 1) s = 1;
    else if (n <= 2) s = 2;
    else if (n <= 5) s = 5;
    else s = 10;
    const candidate = s * power;
    return Math.max(1, Math.ceil(candidate));
  }, []);

  const yDomain = React.useMemo(() => {
    if (!hasData || chartData.length === 0) return { max: 4, step: 1 };
    const maxVal = Math.max(...chartData.map((d) => Number(d.value) || 0));
    const step = niceStep((maxVal || 1) / 4);
    return { max: step * 4, step };
  }, [chartData, hasData, niceStep]);

  return (
    <Card sx={{ 
      width: '100%', 
      height: 260, 
      position: 'relative', 
      backgroundColor: 'transparent !important',
      backgroundImage: 'none !important',
      boxShadow: 'none !important',
      border: 'none !important',
      ...sx 
    }} elevation={0}>
      <Box sx={{ p: 2, pb: 0, display: 'flex', alignItems: 'center', justifyContent: 'flex-start' }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          {IconComponent ? (
            <IconComponent sx={{ fontSize: 22, color }} />
          ) : null}
          <Typography 
            variant="h6"
            sx={{ 
              mb: 0,
              fontWeight: 'bold',
              fontSize: '1rem'
            }}
          >
            {title}
          </Typography>
        </Box>
      </Box>
      <CardContent sx={{ backgroundColor: 'transparent !important', backgroundImage: 'none', boxShadow: 'none', border: 'none' }}>
        <Box sx={{ width: '100%', height: 180 }}>
          {hasData ? (
            <LineChart
              dataset={chartData}
              xAxis={[
                {
                  dataKey: 'date',
                  scaleType: 'point',
                  tickLabelStyle: {
                    fontSize: 12,
                    fill: theme.palette.text.secondary,
                  },
                  valueFormatter: (value) => value,
                  tickSize: 0,
                  tickNumber: 5,
                  disablePadding: false,
                },
              ]}
              yAxis={[
                {
                  tickLabelStyle: {
                    fontSize: 12,
                    fill: theme.palette.text.secondary,
                  },
                  min: 0,
                  max: yDomain.max,
                  tickNumber: 5,
                  valueFormatter: (v) => {
                    if (v === 0) return '';
                    const iv = Math.round(v);
                    return yAxisTickFormatter ? yAxisTickFormatter(iv) : iv;
                  },
                  tickSize: 0,
                  disablePadding: false,
                },
              ]}
              series={[
                {
                  dataKey: 'value',
                  color: color,
                  area: true,
                  showMark: true,
                  valueFormatter: (value) => {
                    if (tooltipFormatter) {
                      try {
                        const result = tooltipFormatter(value, '');
                        if (Array.isArray(result) && result.length >= 1) {
                          return result[0];
                        }
                      } catch (error) {
                        // fallback to default
                      }
                    }
                    return value;
                  },
                },
              ]}
              height={180}
              margin={{ top: 8, right: 16, left: 42, bottom: 28 }}
              slotProps={{
                legend: { hidden: true },
                tooltip: {
                  formatter: formatTooltip,
                },
              }}
              sx={{
                backgroundColor: 'transparent',
                backgroundImage: 'none',
                '& .MuiChartsSurface-root': {
                  background: 'transparent',
                },
                '& .MuiLineElement-root': {
                  strokeWidth: 2,
                },
                '& .MuiMarkElement-root': {
                  stroke: color,
                  strokeWidth: 2,
                  fill: theme.palette.background.paper,
                },
                '& .MuiAreaElement-root': {
                  fill: `url(#${gradientId})`,
                },
                '& .MuiChartsAxis-tick': {
                  display: 'none',
                },
              }}
            >
              <defs>
                <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor={alpha(color, 0.36)} />
                  <stop offset="100%" stopColor={alpha(color, 0)} />
                </linearGradient>
              </defs>
            </LineChart>
          ) : (
            <Box
              sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                height: '100%',
                color: theme.palette.text.secondary,
              }}
            >
              {loading ? 'Loading...' : 'No data available'}
            </Box>
          )}
        </Box>
      </CardContent>
    </Card>
  );
};

export default ServerInfoLineChart;

