import { useContext, useEffect, useState } from 'react';
import { Box, Grid, Typography, FormControl, Select, MenuItem } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import CustomAppBar from '../../components/shared-components/AppBar/AppBar';
import { SettingsContext } from '../../context/SettingsContext';
import Footer from '../../components/shared-components/Footer';
import WeatherWidget from '../../components/dashboard-components/WeatherWidget';
import ServerInfoWidget from '../../components/dashboard-components/ServerInfoWidget';
import ServerInfoLineChart from '../../components/dashboard-components/ServerInfoLineChart';
import DashboardService from '../../services/DashboardService';
import { useUser } from '../../context/UserContext';
import LogDataGrid from '../../components/dashboard-components/LogDataGrid';

const Dashboard = () => {
  const { language, themeMode} = useContext(SettingsContext);
  const theme = useTheme();
  const { userState } = useUser();
  const [todayData, setTodayData] = useState(null);
  const [yesterdayData, setYesterdayData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [refreshingNow, setRefreshingNow] = useState(false);
  const [chartData, setChartData] = useState([]);
  const [maxApiCount7, setMaxApiCount7] = useState(0);
  const [chartRangeDays, setChartRangeDays] = useState(14); // 7 | 14 | 30
  const [yesterdayPickerDate, setYesterdayPickerDate] = useState('');
  const [isYesterdayFromDatePicker, setIsYesterdayFromDatePicker] = useState(false);
  const [logsDateForText, setLogsDateForText] = useState('');
  const [datePickerMin, setDatePickerMin] = useState('2025-05-19');
  const [datePickerMax, setDatePickerMax] = useState('');
  const [logsDatePickerMax, setLogsDatePickerMax] = useState('');
  const [logsDatePickerMin, setLogsDatePickerMin] = useState('2025-05-15');

  const formatDateForTitle = (dateString) => {
    if (!dateString) return 'Yesterday';
    const d = new Date(dateString);
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    const formatted = language === 'cn' ? `${year}/${month}/${day}` : `${day}/${month}/${year}`;
    const prefix = language === 'cn' ? 'Date ' : 'Date ';
    return `${prefix}`;
    // return `${prefix}${formatted}`;
  };

  // 处理API返回的数据格式
  const processLogData = (data) => {
    if (!data) return null;
    
    return {
      cpuUsage: data.cpuUsage || 0,
      memoryUsage: data.memoryUsage || 0,
      memoryFree: data.memoryFree || 0,
      memoryAvailable: data.memoryAvailable || 0,
      diskUsage: data.diskUsage || 0,
      diskFree: data.diskFree || 0,
      apiCount: data.apiCount || 0,
      anonymousCount: data.anonymousCount || 0,
      blogCount: data.blogCount || 0,
      chatbotCount: data.chatbotCount || 0,
      myIpCount: data.myIPCount || 0,
      reportDate: data.reportDate || null
    };
  };

  // 重新获取now数据
  const refreshNowData = async () => {
    if (!userState.access) return;
    
    try {
      setRefreshingNow(true);
      const response = await DashboardService.getLogNow(userState.access);
      setTodayData(processLogData(response));
      // compute logs date from generatedAt
      if (response && response.generatedAt) {
        const dt = new Date(response.generatedAt);
        const computed = new Date(dt);
        // For logs date: if >=22 add 1 day else same day
        const forLogs = new Date(computed);
        if (forLogs.getHours() >= 22) {
          forLogs.setDate(forLogs.getDate() + 1);
        }
        const yy = forLogs.getFullYear();
        const mm = String(forLogs.getMonth() + 1).padStart(2, '0');
        const dd = String(forLogs.getDate()).padStart(2, '0');
        setLogsDateForText(`${yy}-${mm}-${dd}`);

        // DatePicker max rules: previous day if <22:00; today if >=22:00
        const maxDate = (computed.getHours() >= 22)
          ? new Date(computed.getFullYear(), computed.getMonth(), computed.getDate())
          : new Date(computed.getFullYear(), computed.getMonth(), computed.getDate() - 1);
        const maxY = maxDate.getFullYear();
        const maxM = String(maxDate.getMonth() + 1).padStart(2, '0');
        const maxD = String(maxDate.getDate()).padStart(2, '0');
        setDatePickerMax(`${maxY}-${maxM}-${maxD}`);

        // Logs DataGrid max rules: same day inclusive; if >=22:00, next day
        const logsMaxDate = new Date(computed.getFullYear(), computed.getMonth(), computed.getDate());
        if (computed.getHours() >= 22) {
          logsMaxDate.setDate(logsMaxDate.getDate() + 1);
        }
        const logsMaxY = logsMaxDate.getFullYear();
        const logsMaxM = String(logsMaxDate.getMonth() + 1).padStart(2, '0');
        const logsMaxD = String(logsMaxDate.getDate()).padStart(2, '0');
        setLogsDatePickerMax(`${logsMaxY}-${logsMaxM}-${logsMaxD}`);
      }
    } catch (error) {
      console.error('Failed to refresh now data:', error);
    } finally {
      setRefreshingNow(false);
    }
  };

  useEffect(() => {
    const fetchData = async () => {
      if (!userState.access) {
        setLoading(false);
        return;
      }

      try {
        setLoading(true);
        
        // 获取近 (chartRangeDays + 2) 天的日志（AET 基准）：AET+1 天 到 AET-(chartRangeDays) 天；后续再截取最新 chartRangeDays 天
        const now = new Date();
        const sydneyTime = new Date(now.toLocaleString('en-US', { timeZone: 'Australia/Sydney' }));
        const endDate = new Date(sydneyTime);
        endDate.setDate(endDate.getDate() + 1);
        const startDate = new Date(sydneyTime);
        startDate.setDate(startDate.getDate() - chartRangeDays);

        const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
        const params = {
          startDate: fmt(startDate),
          endDate: fmt(endDate),
          sortBy: 'reportdate',
          sortOrder: 'asc'
        };

        // 并行获取今日与区间日志
        const [todayResponse, logs] = await Promise.all([
          DashboardService.getLogNow(userState.access),
          DashboardService.getLogsWithFilter(params, userState.access)
        ]);

        const list = logs?.data || [];
        setTodayData(processLogData(todayResponse));
        // Determine logs date for text API from generatedAt
        if (todayResponse && todayResponse.generatedAt) {
          const dt = new Date(todayResponse.generatedAt);
          const computed = new Date(dt);
          // For logs date: if >=22 add 1 day else same day
          const forLogs = new Date(computed);
          if (forLogs.getHours() >= 22) {
            forLogs.setDate(forLogs.getDate() + 1);
          }
          const yy = forLogs.getFullYear();
          const mm = String(forLogs.getMonth() + 1).padStart(2, '0');
          const dd = String(forLogs.getDate()).padStart(2, '0');
          setLogsDateForText(`${yy}-${mm}-${dd}`);

          // DatePicker max rules: previous day if <22:00; today if >=22:00
          const maxDate = (computed.getHours() >= 22)
            ? new Date(computed.getFullYear(), computed.getMonth(), computed.getDate())
            : new Date(computed.getFullYear(), computed.getMonth(), computed.getDate() - 1);
          const maxY = maxDate.getFullYear();
          const maxM = String(maxDate.getMonth() + 1).padStart(2, '0');
          const maxD = String(maxDate.getDate()).padStart(2, '0');
          setDatePickerMax(`${maxY}-${maxM}-${maxD}`);

          // Logs DataGrid max rules: same day inclusive; if >=22:00, next day
          const logsMaxDate = new Date(computed.getFullYear(), computed.getMonth(), computed.getDate());
          if (computed.getHours() >= 22) {
            logsMaxDate.setDate(logsMaxDate.getDate() + 1);
          }
          const logsMaxY = logsMaxDate.getFullYear();
          const logsMaxM = String(logsMaxDate.getMonth() + 1).padStart(2, '0');
          const logsMaxD = String(logsMaxDate.getDate()).padStart(2, '0');
          setLogsDatePickerMax(`${logsMaxY}-${logsMaxM}-${logsMaxD}`);
        } else {
          setLogsDateForText('');
          setDatePickerMax('');
          setLogsDatePickerMax('');
        }
        // 按日期排序，取最后一条作为“昨日”（考虑时差与端点包含性）
        const sortedByDate = list
          .filter((x) => x && x.reportDate)
          .sort((a, b) => new Date(a.reportDate) - new Date(b.reportDate));
        const latest = sortedByDate.length > 0 ? sortedByDate[sortedByDate.length - 1] : null;
        setYesterdayData(processLogData(latest));
        setYesterdayPickerDate(latest?.reportDate ? new Date(latest.reportDate).toISOString().slice(0,10) : '');
        setIsYesterdayFromDatePicker(false);

        // 规范化数据：在近 N+2 天中截取最新 N 天；x 轴为 MM-DD
        const lastN = sortedByDate.slice(-chartRangeDays);
        const normalized = lastN.map((x) => ({
          date: x.reportDate ? new Date(x.reportDate).toISOString().slice(5, 10) : '',
          memoryUsage: x.memoryUsage ?? 0,
          memoryAvailable: x.memoryAvailable ?? 0,
          apiCount: x.apiCount ?? 0,
          anonymousCount: x.anonymousCount ?? 0,
          chatbotCount: x.chatbotCount ?? 0,
          blogCount: x.blogCount ?? 0,
          myIpCount: x.myIPCount ?? 0,
        }));
        setChartData(normalized);
        // 仍然用最近 7 天计算 max，以保持 API Widget 的参考一致
        const last7ForMax = sortedByDate.slice(-7).map((x) => x.apiCount ?? 0);
        const maxApi = last7ForMax.reduce((max, v) => Math.max(max, v), 0);
        setMaxApiCount7(maxApi);
      } catch (error) {
        console.error('Failed to fetch dashboard data:', error);
        // 如果API调用失败，使用默认数据
        setTodayData({
          cpuUsage: 0,
          memoryUsage: 0,
          memoryFree: 0,
          memoryAvailable: 0,
          diskUsage: 0,
          diskFree: 0,
          apiCount: 0,
          anonymousCount: 0,
          blogCount: 0,
          chatbotCount: 0,
          myIpCount: 0,
          reportDate: null
        });
        setYesterdayData({
          cpuUsage: 0,
          memoryUsage: 0,
          memoryFree: 0,
          memoryAvailable: 0,
          diskUsage: 0,
          diskFree: 0,
          apiCount: 0,
          anonymousCount: 0,
          blogCount: 0,
          chatbotCount: 0,
          myIpCount: 0,
          reportDate: null
        });
        setChartData([]);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [userState.access, chartRangeDays]);

  // Fetch logs text once per pagination/date change with type=all
  useEffect(() => {
    const fetchLogsAll = async () => {
      if (!userState.access || !logsDateForText) return;
      try {
        // Only fetch first page on date change, not on pagination
        const offset = 0;
        const limit = 5; // Default page size
        const res = await DashboardService.getLogText({ date: logsDateForText, type: 'all', offset, limit }, userState.access);
        // This is now just for initial data, pagination is handled by individual components
      } catch (err) {
        console.error('Failed to fetch logs (type=all):', err);
      }
    };
    fetchLogsAll();
  }, [userState.access, logsDateForText]);

  return (
    <Box
      sx={{
        display: 'flex',
        flexDirection: 'column',
      }}
    >
      <CustomAppBar />
      
      {/* 主要内容区域 */}
      <Box
        sx={{
          flex: 1,
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          alignItems: 'center',
          mt: 12,
          px: 2,
        }}
      >
        {/* Server Info Widgets */}
        <Box sx={{ mb: 4 }}>
          <Grid 
            container 
            spacing={{ xs: 2, md: 4 }} 
            justifyContent="center"
            direction={{ xs: 'column', md: 'row' }}
            alignItems="center"
          >
            <Grid item>
              <ServerInfoWidget 
                title="Now" 
                data={todayData}
                loading={loading || refreshingNow}
                onRefresh={refreshNowData}
                sx={{ 
                  boxShadow: 3
                }}
                apiMax7={maxApiCount7}
              />
            </Grid>
            <Grid item>
              <ServerInfoWidget 
                title={isYesterdayFromDatePicker ? formatDateForTitle(yesterdayPickerDate) : 'Yesterday'} 
                data={yesterdayData}
                loading={loading}
                sx={{ 
                  boxShadow: 3
                }}
                apiMax7={maxApiCount7}
                datePickerEnabled
                selectedDate={yesterdayPickerDate}
                onDateChange={async (v)=>{
                  if (!userState.access || !v) return;
                  try{
                    const data = await DashboardService.getLogByDate(v, userState.access);
                    setYesterdayData(processLogData(data));
                    setYesterdayPickerDate(v);
                    setIsYesterdayFromDatePicker(true);
                  }catch(err){
                    console.error('Failed to get log by date', err);
                  }
                }}
                datePickerMin={datePickerMin}
                datePickerMax={datePickerMax}
              />
            </Grid>
          </Grid>
        </Box>

        {/* 近7天折线图 - Mobile: 1x4, Desktop: 2x2 */}
        <Box sx={{ 
          width: '100%', 
          maxWidth: "1120px", 
          mx: 'auto' }}>
          <Grid 
            container 
            spacing={0} 
            columns={{ xs: 1, md: 2 }} 
            justifyContent="center"
            sx={{
              // 为Grid容器添加边框样式
              border: (theme) => `1px solid ${theme.palette.divider}`,
              borderRadius: 1.5,
              overflow: 'hidden',
              backgroundColor: 'background.paper',
            }}
          >
            {/* Trends Title - 跨越整个Grid宽度 */}
            <Grid item xs={1} md={2} sx={{ p: 2, borderBottom: (theme) => `1px solid ${theme.palette.divider}`, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <Typography 
                variant="h5" 
                sx={{ 
                  fontWeight: 'bold',
                  color: 'text.primary',
                  fontSize: { xs: '1.25rem', md: '1.5rem' },
                  textAlign: 'left',
                  marginLeft: 2,
                }}
              >
                Trends
              </Typography>
              
              {/* Date Range Selector */}
              <FormControl size="small" sx={{ minWidth: { xs: 96, md: 110 } }}>
                <Select
                  value={chartRangeDays}
                  onChange={(e) => setChartRangeDays(Number(e.target.value))}
                  displayEmpty
                  MenuProps={{ disableScrollLock: true }}
                  sx={{
                    height: 30,
                  }}
                >
                  <MenuItem value={7}>Last 7d</MenuItem>
                  <MenuItem value={14}>Last 14d</MenuItem>
                  <MenuItem value={30}>Last 30d</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            
            <Grid item xs={1} md={1}>
              <ServerInfoLineChart
                title="Memory Usage"
                data={chartData.map(d => ({
                  ...d,
                  memoryPercent: (d.memoryUsage + d.memoryAvailable) > 0
                    ? Math.round((d.memoryUsage / (d.memoryUsage + d.memoryAvailable)) * 100)
                    : 0
                }))}
                dataKey="memoryPercent"
                color="#ef5350"
                yAxisTickFormatter={(v) => `${v}%`}
                tooltipFormatter={(value) => [`${value}%`, 'Memory Usage']}
                loading={loading}
                IconComponent={require('@mui/icons-material').Memory}
                sx={{
                  // 右侧和底部边框
                  borderRight: (theme) => ({ xs: 'none', md: `1px solid ${theme.palette.divider}` }),
                  borderBottom: (theme) => `1px solid ${theme.palette.divider}`,
                  borderRadius: 0,
                  '&:last-child': {
                    borderBottom: 'none',
                  },
                }}
              />
            </Grid>
            <Grid item xs={1} md={1}>
              <ServerInfoLineChart
                title="API Calls"
                data={chartData}
                dataKey="apiCount"
                color={theme.palette.warning.main}
                loading={loading}
                tooltipFormatter={(value) => [String(value), 'API Calls']}
                IconComponent={require('@mui/icons-material').Api}
                sx={{
                  // 底部边框
                  borderBottom: (theme) => `1px solid ${theme.palette.divider}`,
                  borderRadius: 0,
                  '&:last-child': {
                    borderBottom: 'none',
                  },
                }}
              />
            </Grid>
            <Grid item xs={1} md={1}>
              <ServerInfoLineChart
                title="Anonymous Calls"
                data={chartData}
                dataKey="anonymousCount"
                color={theme.palette.success.main}
                loading={loading}
                tooltipFormatter={(value) => [String(value), 'Anonymous Calls']}
                IconComponent={require('@mui/icons-material').Person}
                sx={{
                  // 右侧和底部边框
                  borderRight: (theme) => ({ xs: 'none', md: `1px solid ${theme.palette.divider}` }),
                  borderBottom: (theme) => `1px solid ${theme.palette.divider}`,
                  borderRadius: 0,
                  '&:last-child': {
                    borderBottom: 'none',
                  },
                }}
              />
            </Grid>
            <Grid item xs={1} md={1}>
              <ServerInfoLineChart
                title="Chatbot Calls"
                data={chartData}
                dataKey="chatbotCount"
                color="#ff7300"
                loading={loading}
                tooltipFormatter={(value) => [String(value), 'Chatbot Calls']}
                IconComponent={require('@mui/icons-material').SmartToy}
                sx={{
                  // 底部边框
                  borderBottom: (theme) => `1px solid ${theme.palette.divider}`,
                  borderRadius: 0,
                  '&:last-child': {
                    borderBottom: 'none',
                  },
                }}
              />
            </Grid>
            <Grid item xs={1} md={1}>
              <ServerInfoLineChart
                title="Blog Calls"
                data={chartData}
                dataKey="blogCount"
                color="#42a5f5"
                loading={loading}
                tooltipFormatter={(value) => [String(value), 'Blog Calls']}
                IconComponent={require('@mui/icons-material').Article}
                sx={{
                  // 右侧和底部边框
                  borderRight: (theme) => ({ xs: 'none', md: `1px solid ${theme.palette.divider}` }),
                  borderBottom: (theme) => `1px solid ${theme.palette.divider}`,
                  borderRadius: 0,
                  '&:last-child': {
                    borderBottom: 'none',
                  },
                }}
              />
            </Grid>
            <Grid item xs={1} md={1}>
              <ServerInfoLineChart
                title="My IPs"
                data={chartData}
                dataKey="myIpCount"
                color="#9f86c0"
                loading={loading}
                tooltipFormatter={(value) => [String(value), 'My IPs']}
                IconComponent={require('@mui/icons-material').LocationOn}
                sx={{
                  // 底部边框
                  borderBottom: (theme) => `1px solid ${theme.palette.divider}`,
                  borderRadius: 0,
                  '&:last-child': {
                    borderBottom: 'none',
                  },
                }}
              />
            </Grid>
          </Grid>
        </Box>

        {/* Logs DataGrid Section */}
        <Box sx={{ width: '100%', maxWidth: '1120px', mt: 4 }}>
          {/* xs: 4x1, md+: 2x2 */}
          <Grid 
            container 
            spacing={0} 
            columns={{ xs: 1, md: 2 }}
            sx={{
              // 为Grid容器添加边框样式
              border: (theme) => `1px solid ${theme.palette.divider}`,
              borderRadius: 1.5,
              overflow: 'hidden',
              backgroundColor: 'background.paper',
            }}
          >
            {/* Logs Title - 跨越整个Grid宽度 */}
            <Grid item xs={1} md={2} sx={{ p: 2, borderBottom: (theme) => `1px solid ${theme.palette.divider}` }}>
              <Typography 
                variant="h5" 
                sx={{ 
                  fontWeight: 'bold',
                  color: 'text.primary',
                  fontSize: { xs: '1.25rem', md: '1.5rem' },
                  textAlign: 'left',
                  marginLeft: 2,
                }}
              >
                Logs
              </Typography>
            </Grid>
            
            <Grid item xs={1} md={1}>
              <LogDataGrid
                title="Anonymous"
                type="anonymous"
                date={logsDateForText}
                accessToken={userState.access}
                datePickerEnabled
                selectedDate={logsDateForText}
                onDateChange={(v)=>{ setLogsDateForText(v); }}
                datePickerMin={logsDatePickerMin}
                datePickerMax={logsDatePickerMax}
                IconComponent={require('@mui/icons-material').Person}
                sx={{
                  // 右侧和底部边框
                  borderRight: (theme) => ({ xs: 'none', md: `1px solid ${theme.palette.divider}` }),
                  borderBottom: (theme) => `1px solid ${theme.palette.divider}`,
                  borderRadius: 0,
                  '&:last-child': {
                    borderBottom: 'none',
                  },
                }}
              />
            </Grid>
            <Grid item xs={1} md={1}>
              <LogDataGrid
                title="Chatbot"
                type="chatbot"
                date={logsDateForText}
                accessToken={userState.access}
                datePickerEnabled
                selectedDate={logsDateForText}
                onDateChange={(v)=>{ setLogsDateForText(v); }}
                datePickerMin={logsDatePickerMin}
                datePickerMax={logsDatePickerMax}
                IconComponent={require('@mui/icons-material').SmartToy}
              />
            </Grid>
            <Grid item xs={1} md={1}>
              <LogDataGrid
                title="Blog"
                type="blog"
                date={logsDateForText}
                accessToken={userState.access}
                datePickerEnabled
                selectedDate={logsDateForText}
                onDateChange={(v)=>{ setLogsDateForText(v); }}
                datePickerMin={logsDatePickerMin}
                datePickerMax={logsDatePickerMax}
                IconComponent={require('@mui/icons-material').Article}
              />
            </Grid>
            <Grid item xs={1} md={1}>
              <LogDataGrid
                title="My IPs"
                type="myip"
                date={logsDateForText}
                accessToken={userState.access}
                datePickerEnabled
                selectedDate={logsDateForText}
                onDateChange={(v)=>{ setLogsDateForText(v); }}
                datePickerMin={logsDatePickerMin}
                datePickerMax={logsDatePickerMax}
                IconComponent={require('@mui/icons-material').LocationOn}
              />
            </Grid>
          </Grid>
        </Box>

        {/* <Box sx={{ mt: 8 }}>
          <WeatherWidget sx={{ width: "400px", height: "400px" }}/>
        </Box> */}
      </Box>

      {/* 下部 Footer */}
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          alignItems: 'center',
          backgroundColor: 'background.default',
          mt: 4,
          borderTop: (theme) => ({
            xs: 'none',
            md: `1px solid ${theme.palette.divider}`,
          }),
          maxWidth: (theme) => theme.breakpoints.values.lg, 
          width: '100%', 
          mx: 'auto',
        }}
      >
        <Footer />
      </Box>

      
    </Box>
  );
};

export default Dashboard;
