import React, { useContext } from 'react';
import { Card, CardContent, Box, Typography, useTheme, useMediaQuery } from '@mui/material';
import { LocalizationProvider, DatePicker } from '@mui/x-date-pickers';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import dayjs from 'dayjs';
import { DataGrid } from '@mui/x-data-grid';
import { useNavigate } from 'react-router-dom';
import DashboardService from '../../services/DashboardService';
import { SettingsContext } from '../../context/SettingsContext';

const LogDataGrid = ({
  title,
  type,
  date,
  accessToken,
  pageSizeOptions = [5, 10, 20],
  IconComponent,
  // Date picking
  datePickerEnabled = false,
  selectedDate = '',
  onDateChange = null,
  datePickerMin = undefined,
  datePickerMax = undefined,
}) => {

  const { language, themeMode} = useContext(SettingsContext);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const navigate = useNavigate();

  const [rows, setRows] = React.useState([]);
  const [rowCount, setRowCount] = React.useState(0);
  const [loading, setLoading] = React.useState(false);
  const [paginationModel, setPaginationModel] = React.useState({ page: 0, pageSize: 5 });

  const buildBaseColumns = React.useCallback(() => {
    if (type === 'myip') {
      return [
        { 
          field: 'ip', 
          headerName: 'IP',
          renderCell: (params) => (
            <Typography
              sx={{
                color: theme.palette.primary.main,
                cursor: 'pointer',
                textDecoration: 'underline',
                fontSize: 'inherit',
                lineHeight: 'normal',
                margin: 0,
                padding: 0,
                display: 'flex',
                alignItems: 'center',
                height: '100%',
                '&:hover': {
                  color: theme.palette.primary.dark,
                }
              }}
              onClick={(e) => {
                e.stopPropagation();
                if (params.value) {
                  window.open(`https://www.abuseipdb.com/check/${params.value}`, '_blank');
                }
              }}
            >
              {params.value}
            </Typography>
          )
        },
      ];
    }
    if (type === 'chatbot') {
      return [
        { field: 'time', headerName: 'Time' },
        { field: 'question', headerName: 'Question' },
        { field: 'location', headerName: 'Location' },
        { 
          field: 'ip', 
          headerName: 'IP',
          renderCell: (params) => (
            <Typography
              sx={{
                color: theme.palette.primary.main,
                cursor: 'pointer',
                textDecoration: 'underline',
                fontSize: 'inherit',
                lineHeight: 'normal',
                margin: 0,
                padding: 0,
                display: 'flex',
                alignItems: 'center',
                height: '100%',
                '&:hover': {
                  color: theme.palette.primary.dark,
                }
              }}
              onClick={(e) => {
                e.stopPropagation();
                if (params.value) {
                  window.open(`https://www.abuseipdb.com/check/${params.value}`, '_blank');
                }
              }}
            >
              {params.value}
            </Typography>
          )
        },
      ];
    }
    if (type === 'blog') {
      return [
        { field: 'time', headerName: 'Time' },
        { 
          field: 'blogid', 
          headerName: 'Blog ID',
          renderCell: (params) => (
            <Typography
              sx={{
                color: theme.palette.primary.main,
                cursor: 'pointer',
                textDecoration: 'underline',
                fontSize: 'inherit',
                lineHeight: 'normal',
                margin: 0,
                padding: 0,
                display: 'flex',
                alignItems: 'center',
                height: '100%',
                '&:hover': {
                  color: theme.palette.primary.dark,
                }
              }}
              onClick={(e) => {
                e.stopPropagation();
                if (params.value) {
                  window.open(`/blog/${params.value}`, '_blank');
                }
              }}
            >
              {params.value}
            </Typography>
          )
        },
        { field: 'location', headerName: 'Location' },
        { 
          field: 'ip', 
          headerName: 'IP',
          renderCell: (params) => (
            <Typography
              sx={{
                color: theme.palette.primary.main,
                cursor: 'pointer',
                textDecoration: 'underline',
                fontSize: 'inherit',
                lineHeight: 'normal',
                margin: 0,
                padding: 0,
                display: 'flex',
                alignItems: 'center',
                height: '100%',
                '&:hover': {
                  color: theme.palette.primary.dark,
                }
              }}
              onClick={(e) => {
                e.stopPropagation();
                if (params.value) {
                  window.open(`https://www.abuseipdb.com/check/${params.value}`, '_blank');
                }
              }}
            >
              {params.value}
            </Typography>
          )
        },
      ];
    }
    // anonymous
    return [
      { field: 'time', headerName: 'Time' },
      { field: 'location', headerName: 'Location' },
      { 
        field: 'ip', 
        headerName: 'IP',
        renderCell: (params) => (
          <Typography
            sx={{
              color: theme.palette.primary.main,
              cursor: 'pointer',
              textDecoration: 'underline',
              fontSize: 'inherit',
              lineHeight: 'normal',
              margin: 0,
              padding: 0,
              display: 'flex',
              alignItems: 'center',
              height: '100%',
              '&:hover': {
                color: theme.palette.primary.dark,
              }
            }}
            onClick={(e) => {
              e.stopPropagation();
              if (params.value) {
                window.open(`https://www.abuseipdb.com/check/${params.value}`, '_blank');
              }
            }}
          >
            {params.value}
          </Typography>
        )
      },
    ];
  }, [type, theme]);

  const [columns, setColumns] = React.useState(buildBaseColumns());

  React.useEffect(() => {
    setColumns(buildBaseColumns());
  }, [buildBaseColumns]);

  const autoSizeColumns = React.useCallback((dataRows, cols) => {
    if (!Array.isArray(cols) || cols.length === 0) return cols;
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return cols;
    const fontSize = typeof theme.typography.body2.fontSize === 'number'
      ? `${theme.typography.body2.fontSize}px`
      : (theme.typography.body2.fontSize || '14px');
    const fontFamily = theme.typography.fontFamily || 'sans-serif';
    ctx.font = `${fontSize} ${fontFamily}`;

    const PADDING = 32; // cell padding + sort icon space
    const MAX = 600; // cap to avoid overflow
    const MIN = 40;

    const measure = (text) => {
      const t = String(text ?? '');
      const metrics = ctx.measureText(t);
      return Math.ceil(metrics.width);
    };

    const sized = cols.map((col) => {
      const header = col.headerName || col.field;
      let maxW = measure(header);
      for (const r of dataRows) {
        const v = r[col.field];
        maxW = Math.max(maxW, measure(v));
      }
      const width = Math.max(MIN, Math.min(MAX, maxW + PADDING));
      return { ...col, width };
    });
    return sized;
  }, [theme]);

  const fetchPage = React.useCallback(async () => {
    if (!accessToken || !date || !type) return;
    try {
      setLoading(true);
      const offset = paginationModel.page * paginationModel.pageSize;
      const limit = paginationModel.pageSize;
      const order = 'desc';
      const res = await DashboardService.getLogText({ date, type, offset, limit, order }, accessToken);

      if (type === 'myip') {
        const ips = res?.myip || res?.ips || [];
        const mapped = (ips || []).map((ip, idx) => ({ id: offset + idx + 1, ip }));
        setRows(mapped);
        setRowCount(res?.total || mapped.length || 0);
        setColumns((prev) => autoSizeColumns(mapped, buildBaseColumns()));
      } else if (type === 'anonymous') {
        const data = res?.anonymous || res?.data || [];
        const mapped = data.map((it, idx) => ({ id: offset + idx + 1, ...it }));
        setRows(mapped);
        setRowCount(res?.total || data.length || 0);
        setColumns((prev) => autoSizeColumns(mapped, buildBaseColumns()));
      } else if (type === 'blog') {
        const data = res?.blog || res?.data || [];
        const mapped = data.map((it, idx) => ({ id: offset + idx + 1, ...it }));
        setRows(mapped);
        setRowCount(res?.total || data.length || 0);
        setColumns((prev) => autoSizeColumns(mapped, buildBaseColumns()));
      } else if (type === 'chatbot') {
        const data = res?.chatbot || res?.data || [];
        const mapped = data.map((it, idx) => ({ id: offset + idx + 1, ...it }));
        setRows(mapped);
        setRowCount(res?.total || data.length || 0);
        setColumns((prev) => autoSizeColumns(mapped, buildBaseColumns()));
      }
    } catch (err) {
      console.error('Failed to load log text:', err);
      setRows([]);
      setRowCount(0);
    } finally {
      setLoading(false);
    }
  }, [accessToken, date, type, paginationModel.page, paginationModel.pageSize, autoSizeColumns, buildBaseColumns]);

  React.useEffect(() => {
    if (accessToken && date && type) {
      fetchPage();
    }
  }, [accessToken, date, type, paginationModel.page, paginationModel.pageSize]);

  const iconColor = React.useMemo(() => {
    if (type === 'anonymous') return theme.palette.success.main;
    if (type === 'chatbot') return '#ff7300';
    if (type === 'blog') return '#42a5f5';
    if (type === 'myip') return '#9f86c0';
    return theme.palette.text.secondary;
  }, [type, theme]);

  // 自定义滚动条样式，与SettingsContext保持一致
  const scrollbarStyle = React.useMemo(() => {
    const trackColor = 'transparent';
    const thumbColor = theme.palette.mode === 'dark' ? '#3a3a3a' : '#c0c0c0';
    const hoverColor = theme.palette.mode === 'dark' ? '#5a5a5a' : '#a0a0a0';

    return `
      .log-data-grid-scrollbar::-webkit-scrollbar-track {
        background: ${trackColor};
      }
      .log-data-grid-scrollbar::-webkit-scrollbar-thumb {
        background: ${thumbColor};
        border-radius: 2px;
      }
      .log-data-grid-scrollbar::-webkit-scrollbar-thumb:hover {
        background: ${hoverColor};
      }
      /* Hide horizontal scrollbar (WebKit) inside the virtual scroller */
      .log-data-grid-scrollbar .MuiDataGrid-virtualScroller::-webkit-scrollbar:horizontal {
        height: 0 !important;
        display: none !important;
      }
      /* Ensure the MUI overlay horizontal scrollbar is hidden */
      .log-data-grid-scrollbar .MuiDataGrid-scrollbar--horizontal {
        display: none !important;
        height: 0 !important;
      }
    `;
  }, [theme.palette.mode]);

  return (
    <Card sx={{ width: '100%', height: 360, display: 'flex', flexDirection: 'column', backgroundColor: 'transparent', backgroundImage: 'none', boxShadow: 'none', border: '1px solid transparent' }} elevation={0}>
      <style>{scrollbarStyle}</style>
      <Box sx={{ p: 2, pb: 1, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          {IconComponent ? (
            <IconComponent sx={{ fontSize: 20, color: iconColor }} />
          ) : null}
          <Typography variant="h6" sx={{ fontWeight: 'bold', fontSize: '1rem' }}>{title}</Typography>
        </Box>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
          {datePickerEnabled ? (
            <LocalizationProvider dateAdapter={AdapterDayjs}>
              <DatePicker
                value={selectedDate ? dayjs(selectedDate) : null}
                onChange={(v) => onDateChange && onDateChange(v ? v.format('YYYY-MM-DD') : '')}
                minDate={datePickerMin ? dayjs(datePickerMin) : undefined}
                maxDate={datePickerMax ? dayjs(datePickerMax) : undefined}
                format="YYYY-MM-DD"
                slotProps={{
                  textField: {
                    size: 'small',
                    sx: {
                      width: isMobile ? 130 : 150,
                      minWidth: isMobile ? 130 : 150,
                      height: 30,
                      '& .MuiOutlinedInput-root': {
                        height: 30,
                        borderRadius: 2,
                        '& .MuiOutlinedInput-input': {
                          padding: '0 8px',
                          height: '30px',
                          lineHeight: '30px',
                        },
                      },
                    },
                  },
                }}
              />
            </LocalizationProvider>
          ) : null}
          <Typography variant="body" sx={{ color: 'text.secondary', fontWeight: 500 }}>
            {rowCount}
          </Typography>
        </Box>
      </Box>
      <CardContent sx={{ pt: 1, flex: 1, display: 'flex', backgroundColor: 'transparent' }}>
        <Box sx={{ width: '100%', height: '100%' }}>
          <DataGrid
            rows={rows}
            columns={columns}
            pagination
            paginationMode="server"
            rowCount={rowCount}
            loading={loading}
            paginationModel={paginationModel}
            onPaginationModelChange={setPaginationModel}
            pageSizeOptions={pageSizeOptions}
            disableColumnMenu
            disableRowSelectionOnClick
            density="compact"
            className="log-data-grid-scrollbar"
            sx={{ 
              '&, [class^=MuiDataGrid]': { border: 'none' }, 
              /* Hide Rows per page label and page-size select */
              '& .MuiDataGrid-footerContainer .MuiTablePagination-selectLabel': {
                display: 'none',
              },
              '& .MuiDataGrid-footerContainer .MuiTablePagination-input': {
                display: 'none',
              }
            }}
          />
        </Box>
      </CardContent>
    </Card>
  );
};

export default LogDataGrid;